const incoming = $input.first().json;
const item = incoming.body ?? incoming;
const eventId = typeof item.event_id === 'string' ? item.event_id.trim() : '';
const packagePath = typeof item.package_path === 'string'
  ? item.package_path.trim().replace(/^\/mnt\/c\/_mcp\/muse-packages\//, '')
  : '';
const inputFile = typeof item.package_filename === 'string' ? item.package_filename.trim() : '';
const outputFile = 'hallazgos.zip';

if (!eventId || !packagePath || !inputFile) {
  throw new Error('event_id, package_path y package_filename son obligatorios.');
}
if (!packagePath.split('/').every(part => /^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(part))
    || !/^[A-Za-z0-9][A-Za-z0-9._-]*\.zip$/.test(inputFile)
    || inputFile.toLowerCase() === outputFile) {
  throw new Error('La ruta o el nombre del ZIP no son compatibles con Kanban.');
}

return [{
  json: {
    project_id: 1,
    title: `Investigar: ${item.title || eventId}`,
    description: item.summary || 'Investigar dolor de mercado y fuentes oficiales.',
    assigned_to: 'brio',
    priority: item.interest_level === 'HIGH' ? 'HIGH' : 'MEDIUM',
    metadata: {
      radar: item.radar_source || item.radar || 'gobierno-nl',
      event_id: eventId,
      ...(item.packaged_at ? { package_version: item.packaged_at } : {}),
      muse_zip: { path: packagePath, input_file: inputFile, output_file: outputFile }
    }
  }
}];

